META = dict(nama="Logistics", jp="物流倉庫", emoji="📦", co="物流会社・倉庫")
SPEC = dict(kerja="荷物を正確に、安全に扱っている", kerja_id="menangani barang dengan akurat dan aman", soal={
 "shibou-01": ("なぜ物流の仕事を選びましたか。", "Mengapa Anda memilih pekerjaan logistik?", "ネットで買った荷物が、お客様に届くまでの仕事に、興味があります。人の生活を支える仕事がしたいです。", "Saya tertarik pada pekerjaan di balik barang belanja online sampai ke pelanggan. Saya ingin bekerja menopang kehidupan orang.", [("物流", "logistik"), ("倉庫", "gudang"), ("届ける", "mengantarkan"), ("支える", "menopang")]),
 "shibou-02": ("なぜ日本で物流の仕事を学びたいですか。", "Mengapa Anda ingin belajar logistik di Jepang?", "日本の倉庫は、荷物の管理が正確で、とても整理されていると聞きました。その方法を学びたいです。", "Saya dengar gudang di Jepang mengelola barang dengan akurat dan sangat tertata. Saya ingin mempelajari metodenya.", [("管理", "pengelolaan"), ("整理", "penataan"), ("正確", "akurat")]),
 "shibou-04": ("この仕事に興味を持った理由は何ですか。", "Apa alasan Anda tertarik pada pekerjaan ini?", "荷物を、間違えないで、早くお客様に届けるために、みんなが協力します。その一人になりたいです。", "Banyak orang bekerja sama agar barang sampai ke pelanggan dengan cepat tanpa keliru. Saya ingin menjadi salah satunya.", [("協力", "kerja sama"), ("届ける", "mengantarkan"), ("興味", "minat")]),
 "shibou-05": ("物流の仕事で、一番楽しみなことは何ですか。", "Apa yang paling Anda nantikan dari pekerjaan logistik?", "フォークリフトなどの機械の使い方を覚えて、できる仕事を増やすことです。日本の管理方法も学びたいです。", "Mempelajari cara memakai mesin seperti forklift sehingga pekerjaan yang bisa saya lakukan bertambah. Saya juga ingin belajar cara pengelolaan Jepang.", [("フォークリフト", "forklift"), ("機械", "mesin"), ("楽しみ", "dinantikan")]),
 "shigoto-01": ("物流倉庫の主な仕事は何だと思いますか。", "Menurut Anda, apa pekerjaan utama gudang logistik?", "荷物を受け取って、保管して、注文に合わせて取り出して、出荷する仕事だと思います。", "Saya kira pekerjaannya menerima barang, menyimpannya, mengambilnya sesuai pesanan, lalu mengirimkannya.", [("保管", "penyimpanan"), ("出荷", "pengiriman"), ("入荷", "penerimaan barang")]),
 "shigoto-02": ("朝早くや、夜遅くに働くことはできますか。", "Bisakah Anda bekerja pagi buta atau larut malam?", "はい、できます。シフトの時間に合わせて、体調を整えます。", "Ya, bisa. Saya menyesuaikan kondisi badan dengan jam shift.", [("シフト", "shift"), ("体調", "kondisi badan"), ("早朝", "pagi buta")]),
 "shigoto-03": ("一日中、立って歩いて、作業できますか。", "Bisakah Anda berdiri dan berjalan bekerja seharian?", "はい、大丈夫です。歩くのも、立つのも、慣れています。休けいのときに、足を休めます。", "Ya, tidak masalah. Saya terbiasa berjalan dan berdiri. Saat istirahat saya mengistirahatkan kaki.", [("立つ", "berdiri"), ("歩く", "berjalan"), ("休けい", "istirahat")]),
 "shigoto-04": ("倉庫の中の、暑さや寒さがあっても大丈夫ですか。", "Apakah Anda baik-baik saja dengan panas dan dingin di dalam gudang?", "はい、大丈夫です。夏はこまめに水を飲んで、冬は服をたくさん着ます。冷凍倉庫のときは、防寒着を使います。", "Ya, tidak masalah. Saat musim panas saya sering minum air, saat dingin memakai banyak lapis pakaian. Untuk gudang beku saya memakai jaket penahan dingin.", [("暑さ", "panas"), ("寒さ", "dingin"), ("防寒着", "pakaian penahan dingin")]),
 "shigoto-05": ("重い荷物を持つ体力はありますか。", "Apakah Anda punya stamina untuk mengangkat barang berat?", "はい、あります。毎日運動をして、体力をつけています。重いものは、腰に気をつけて、台車を使います。", "Ya, ada. Saya berolahraga setiap hari. Barang berat saya angkat dengan menjaga pinggang dan memakai troli.", [("台車", "troli"), ("腰", "pinggang"), ("体力", "stamina")]),
 "shigoto-06": ("年末など、荷物が多い時期に、残業があっても大丈夫ですか。", "Apakah Anda baik-baik saja dengan lembur saat barang banyak, misalnya akhir tahun?", "はい、大丈夫です。忙しい時期は、チームでがんばります。体調にも気をつけます。", "Ya, tidak masalah. Saat sibuk kami berusaha bersama. Saya juga menjaga kondisi badan.", [("繁忙期", "musim sibuk"), ("残業", "lembur"), ("チーム", "tim")]),
 "shigoto-07": ("フォークリフトや、台車を使うとき、何に気をつけますか。", "Apa yang Anda perhatikan saat memakai forklift dan troli?", "必ず、使い方を教えてもらってから使います。まわりに人がいないか、見ます。スピードを出しません。", "Saya hanya memakainya setelah diajari cara pakainya. Saya memeriksa apakah ada orang di sekitar. Saya tidak melaju kencang.", [("フォークリフト", "forklift"), ("台車", "troli"), ("スピード", "kecepatan")]),
 "shigoto-08": ("倉庫の中の、ほこりや、機械の音がある環境でも大丈夫ですか。", "Apakah Anda baik-baik saja dengan debu dan suara mesin di gudang?", "はい、大丈夫です。必要なときは、マスクや耳せんをつけます。", "Ya, tidak masalah. Bila perlu saya memakai masker dan penyumbat telinga.", [("ほこり", "debu"), ("マスク", "masker"), ("耳せん", "penyumbat telinga")]),
 "shigoto-09": ("荷物を扱う仕事で、大切なことは何だと思いますか。", "Menurut Anda, apa yang penting dalam menangani barang?", "間違えないで、正確に仕事をすることだと思います。荷物を、ていねいに扱うことも大切です。", "Menurut saya, bekerja dengan akurat tanpa keliru. Menangani barang dengan hati-hati juga penting.", [("正確", "akurat"), ("扱う", "menangani"), ("ていねい", "hati-hati")]),
 "shigoto-10": ("荷物が倉庫に着いてから、出るまで、どんな作業がありますか。", "Pekerjaan apa saja sejak barang tiba di gudang sampai keluar?", "荷物を受け取って、検品して、棚に置きます。注文が来たら、取り出して、箱に入れて、出荷します。", "Barang diterima, diperiksa, lalu ditaruh di rak. Saat pesanan datang, barang diambil, dimasukkan ke kotak, dan dikirim.", [("検品", "pemeriksaan barang"), ("棚", "rak"), ("ピッキング", "pengambilan barang")]),
 "shigoto-11": ("荷物の数や、種類を確認する作業は、得意ですか。", "Apakah Anda pandai memeriksa jumlah dan jenis barang?", "はい、得意です。ミスをしないように、二回確認します。伝票と荷物を、よく見くらべます。", "Ya, saya pandai. Agar tidak salah, saya memeriksa dua kali. Saya membandingkan nota dengan barang secara teliti.", [("伝票", "nota/slip"), ("確認", "memastikan"), ("見くらべる", "membandingkan")]),
 "shigoto-12": ("荷物が壊れているのを見つけたら、どうしますか。", "Apa yang Anda lakukan kalau menemukan barang rusak?", "勝手に処理しないで、すぐに責任者に報告します。写真や、メモも残します。", "Saya tidak menanganinya sendiri, segera melapor kepada penanggung jawab. Saya juga menyimpan foto dan catatan.", [("破損", "kerusakan"), ("報告", "melapor"), ("写真", "foto")]),
 "shigoto-13": ("バーコードや、パソコンの画面を見て、作業することはできますか。", "Apakah Anda bisa bekerja dengan memindai barcode dan melihat layar komputer?", "はい、できます。まだ分からないところは、先輩に聞いて、早く覚えたいです。", "Ya, bisa. Bagian yang belum paham saya tanyakan kepada senior dan ingin segera menguasainya.", [("バーコード", "barcode"), ("画面", "layar"), ("覚える", "menguasai")]),
 "taiou-02": ("荷物を間違えて、出荷してしまったら、どうしますか。", "Apa yang Anda lakukan kalau keliru mengirim barang?", "すぐに正直に責任者に報告します。どうして間違えたか考えて、次は確認を増やします。", "Saya segera melapor jujur kepada penanggung jawab. Saya memikirkan penyebabnya dan menambah pengecekan berikutnya.", [("間違える", "keliru"), ("報告", "melapor"), ("確認", "pengecekan")]),
 "taiou-06": ("急に、荷物が増えたり、予定が変わったりしたら、どうしますか。", "Apa yang Anda lakukan kalau barang mendadak bertambah atau rencana berubah?", "責任者の指示をよく聞いて、作業の順番を変えます。分からないときは、すぐに聞きます。", "Saya mendengarkan instruksi penanggung jawab dan mengubah urutan kerja. Kalau tidak paham, saya langsung bertanya.", [("急に", "mendadak"), ("順番", "urutan"), ("指示", "instruksi")]),
 "taiou-08": ("出荷の時間に、間に合いそうにないとき、どうしますか。", "Apa yang Anda lakukan kalau sepertinya tidak sempat mengejar jam pengiriman?", "あせらないで、すぐに責任者に報告します。ほかの人に手伝ってもらえるか、聞きます。", "Saya tidak panik dan segera melapor kepada penanggung jawab. Saya menanyakan apakah ada yang bisa membantu.", [("間に合う", "sempat"), ("あせる", "panik"), ("手伝う", "membantu")]),
 "taiou-11": ("忙しい時期で、疲れているとき、どう気持ちを保ちますか。", "Bagaimana Anda menjaga semangat saat sibuk dan lelah?", "忙しい時期は短いと理解しています。しっかり寝て、食事をとって、体調を保ちます。", "Saya paham musim sibuk itu singkat. Saya tidur cukup, makan baik, dan menjaga kondisi badan.", [("疲れる", "lelah"), ("体調", "kondisi badan"), ("睡眠", "tidur")]),
 "taiou-12": ("先輩の説明が早くて、分からないとき、どうしますか。", "Apa yang Anda lakukan kalau penjelasan senior terlalu cepat dan tidak Anda pahami?", "「すみません、もう一度ゆっくりお願いします」と言います。分からない言葉は、メモして、あとで聞きます。", "Saya bilang \"Maaf, tolong ulangi lebih pelan\". Kata yang tidak paham saya catat dan tanyakan nanti.", [("説明", "penjelasan"), ("ゆっくり", "pelan"), ("メモ", "catatan")]),
 "tim-01": ("荷物が多いとき、チームの人と、どのように作業を分けますか。", "Saat barang banyak, bagaimana Anda membagi kerja dengan tim?", "責任者の指示で、受け取る人、棚に置く人、箱に入れる人などに分かれます。早く終わったら、ほかの人を手伝います。", "Sesuai instruksi penanggung jawab, ada yang menerima, menata di rak, dan mengemas. Kalau selesai lebih dulu, saya membantu yang lain.", [("分担", "pembagian tugas"), ("棚", "rak"), ("手伝う", "membantu")]),
 "tim-02": ("作業の方法や、場所が分からなかったとき、どうしますか。", "Apa yang Anda lakukan kalau tidak tahu cara kerja atau lokasi?", "すぐに先輩に聞きます。分からないまま動くと、荷物を間違えることがあるからです。", "Saya segera bertanya kepada senior. Bergerak tanpa paham bisa menyebabkan keliru barang.", [("場所", "lokasi"), ("方法", "cara"), ("間違える", "keliru")]),
 "tim-03": ("フォークリフトを使うとき、まわりの人と、どのようにコミュニケーションをとりますか。", "Bagaimana Anda berkomunikasi dengan orang sekitar saat memakai forklift?", "動く前に、声をかけて、まわりの人に知らせます。曲がり角では、一度止まって、確認します。", "Sebelum bergerak saya memberi aba-aba kepada orang sekitar. Di tikungan saya berhenti sekali untuk memeriksa.", [("曲がり角", "tikungan"), ("確認", "memastikan"), ("知らせる", "memberi tahu")]),
 "tim-04": ("倉庫の仲間と、どのように仲良くなりたいですか。", "Bagaimana Anda ingin akrab dengan rekan di gudang?", "毎日、元気にあいさつをします。教えてもらったときは、「ありがとうございます」と言います。", "Setiap hari saya menyapa dengan semangat. Saat diajari, saya mengatakan \"Terima kasih\".", [("あいさつ", "salam"), ("仲間", "rekan"), ("仲良くなる", "menjadi akrab")]),
 "anzen-01": ("倉庫で、必ず身につけるものは何ですか。", "Apa yang wajib dikenakan di gudang?", "ヘルメット、安全靴、作業服を必ず着けます。必要なときは、手袋や、反射する安全ベストも使います。", "Saya wajib memakai helm, sepatu keselamatan, dan pakaian kerja. Bila perlu saya juga memakai sarung tangan dan rompi reflektif.", [("ヘルメット", "helm"), ("安全靴", "sepatu keselamatan"), ("安全ベスト", "rompi keselamatan")]),
 "anzen-02": ("フォークリフトが動いているとき、近くを歩くときは、どうしますか。", "Apa yang Anda lakukan saat berjalan di dekat forklift yang bergerak?", "運転する人に、合図をして、目が合ってから通ります。フォークの前や、荷物の下には、絶対に入りません。", "Saya memberi isyarat kepada pengemudi dan lewat setelah kontak mata. Saya sama sekali tidak masuk ke depan garpu atau bawah muatan.", [("フォーク", "garpu forklift"), ("合図", "isyarat"), ("通る", "lewat")]),
 "anzen-03": ("荷物を高い所に置いたり、取ったりするとき、何に気をつけますか。", "Apa yang Anda perhatikan saat menaruh dan mengambil barang di tempat tinggi?", "荷物が落ちないか、確認します。脚立は、ぐらぐらしないか、見ます。重いものは、高い所に置きません。", "Saya memeriksa apakah barang bisa jatuh. Saya melihat apakah tangga tidak goyah. Barang berat tidak saya taruh di tempat tinggi.", [("脚立", "tangga lipat"), ("落ちる", "jatuh"), ("確認", "memastikan")]),
 "anzen-04": ("重い荷物を運ぶとき、どうしますか。", "Apa yang Anda lakukan saat mengangkat barang berat?", "一人で持てないときは、ほかの人に頼みます。腰を曲げないで、ひざを使って持ち上げます。", "Kalau tidak sanggup sendiri, saya minta bantuan orang lain. Saya mengangkat dengan menekuk lutut, bukan membungkuk dari pinggang.", [("腰", "pinggang"), ("ひざ", "lutut"), ("頼む", "meminta bantuan")]),
 "seikatsu-07": ("倉庫が多い、町の外の地域での生活に、不便なことがあっても大丈夫ですか。", "Apakah Anda baik-baik saja dengan ketidaknyamanan hidup di kawasan pinggiran yang banyak gudang?", "大丈夫です。寮から倉庫までの行き方を、調べておきます。お店が遠いときは、まとめて買い物をします。", "Tidak masalah. Saya akan mengecek rute dari asrama ke gudang. Kalau toko jauh, saya belanja sekaligus.", [("寮", "asrama"), ("まとめて", "sekaligus"), ("通勤", "berangkat kerja")]),
 "seikatsu-08": ("日本の宅配サービスについて、知っていることはありますか。", "Apa yang Anda ketahui tentang layanan pengiriman paket di Jepang?", "日本の宅配は、時間を指定できて、とても正確だと聞きました。荷物をていねいに扱うことも、知っています。", "Saya dengar pengiriman paket di Jepang bisa menentukan waktu dan sangat akurat. Saya juga tahu barang ditangani dengan hati-hati.", [("宅配", "pengiriman paket"), ("時間指定", "penentuan waktu"), ("ていねい", "hati-hati")]),
 "mokuhyou-05": ("日本で物流の仕事を学んだあと、自分の国でどんなことをしたいですか。", "Setelah belajar logistik di Jepang, apa yang ingin Anda lakukan di negara sendiri?", "日本で学んだ荷物の管理や、安全の方法を使って、自分の国の倉庫や物流の仕事をしたいです。", "Saya ingin bekerja di gudang atau logistik negara saya dengan memakai pengelolaan barang dan cara keselamatan yang saya pelajari di Jepang.", [("管理", "pengelolaan"), ("安全", "keselamatan"), ("倉庫", "gudang")]),
})
